// Lightweight React-style component system (no build step required)
// ---------------------------------------------------------------------------

const h = (tag, props, ...children) => {
  const el = document.createElement(tag);
  if (props) {
    for (const [key, val] of Object.entries(props)) {
      if (key === 'className')       el.className = val;
      else if (key === 'htmlFor')    el.htmlFor = val;
      else if (key === 'style')      Object.assign(el.style, val);
      else if (key.startsWith('on')) el.addEventListener(key.slice(2).toLowerCase(), val);
      else if (val !== false && val !== null && val !== undefined)
        el.setAttribute(key, val);
    }
  }
  children.flat(Infinity).forEach(child => {
    if (child == null || child === false) return;
    el.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  });
  return el;
};

const svg = (paths, attrs = {}) => {
  const ns = 'http://www.w3.org/2000/svg';
  const el = document.createElementNS(ns, 'svg');
  Object.assign(el, { setAttribute: el.setAttribute.bind(el) });
  const defaults = { width: '16', height: '16', viewBox: '0 0 24 24', fill: 'none',
                     stroke: 'currentColor', 'stroke-width': '2',
                     'stroke-linecap': 'round', 'stroke-linejoin': 'round', ...attrs };
  for (const [k, v] of Object.entries(defaults)) el.setAttribute(k, v);
  el.innerHTML = paths;
  return el;
};

// SVG icon helpers
const IconUser  = () => svg('<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>');
const IconMail  = () => svg('<rect width="20" height="16" x="2" y="4" rx="2"/><path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"/>');
const IconPhone = () => svg('<path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07A19.5 19.5 0 0 1 4.15 12a19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 3.06 1h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L7.09 8.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/>');
const IconInfo  = () => svg('<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>');
const IconAlert = () => svg('<circle cx="12" cy="12" r="10"/><line x1="12" x2="12" y1="8" y2="12"/><line x1="12" x2="12.01" y1="16" y2="16"/>');
const IconCheck = () => svg('<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>');
const IconSend  = () => svg('<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>');

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

const state = {
  values:  { fullName: '', email: '', phone: '' },
  touched: { fullName: false, email: false, phone: false },
  submitting: false,
  submitted: false,
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\+?[\d\s\-().]{7,20}$/;

function validate(values) {
  const errors = {};
  if (!values.fullName.trim())          errors.fullName = 'Full name is required.';
  if (!values.email.trim())             errors.email = 'Email address is required.';
  else if (!EMAIL_RE.test(values.email)) errors.email = 'Enter a valid email address.';
  if (values.phone.trim() && !PHONE_RE.test(values.phone))
    errors.phone = 'Phone number format is invalid.';
  return errors;
}

// ---------------------------------------------------------------------------
// Render
// ---------------------------------------------------------------------------

function FormField({ id, label, required, inputProps, helperText, errorText }) {
  const hasError = !!errorText;
  const wrapper = h('div', { className: `form-field${hasError ? ' has-error' : ''}` },
    h('label', { htmlFor: id },
      label,
      required
        ? h('span', { className: 'required-star' }, ' *')
        : h('span', { className: 'optional-tag' }, '(optional)')
    ),
    h('div', { className: 'input-wrapper' },
      h('input', { id, ...inputProps }),
      h('span', { className: 'input-icon' }, inputProps['data-icon']())
    ),
    helperText && !hasError
      ? h('p', { className: 'helper-text' }, IconInfo(), helperText)
      : null,
    hasError
      ? h('p', { className: 'error-text' }, IconAlert(), errorText)
      : null
  );
  return wrapper;
}

function render() {
  const root = document.getElementById('root');
  root.innerHTML = '';

  const errors  = validate(state.values);
  const canSubmit = !state.submitting;

  // ---- Fields ----

  const fullNameField = FormField({
    id: 'fullName',
    label: 'Full Name',
    required: true,
    errorText: state.touched.fullName ? errors.fullName : null,
    inputProps: {
      type: 'text',
      name: 'fullName',
      placeholder: 'Jane Smith',
      value: state.values.fullName,
      autocomplete: 'name',
      'data-icon': IconUser,
      onInput(e) {
        state.values.fullName = e.target.value;
        state.touched.fullName = true;
        render();
      },
      onBlur() {
        state.touched.fullName = true;
        render();
      },
    },
  });

  const emailField = FormField({
    id: 'email',
    label: 'Email Address',
    required: true,
    errorText: state.touched.email ? errors.email : null,
    inputProps: {
      type: 'email',
      name: 'email',
      placeholder: 'jane@example.com',
      value: state.values.email,
      autocomplete: 'email',
      'data-icon': IconMail,
      onInput(e) {
        state.values.email = e.target.value;
        state.touched.email = true;
        render();
      },
      onBlur() {
        state.touched.email = true;
        render();
      },
    },
  });

  const phoneField = FormField({
    id: 'phone',
    label: 'Phone Number',
    required: false,
    helperText: 'Include country code if outside the US, e.g. +1 (555) 000-0000',
    errorText: state.touched.phone ? errors.phone : null,
    inputProps: {
      type: 'tel',
      name: 'phone',
      placeholder: '+1 (555) 000-0000',
      value: state.values.phone,
      autocomplete: 'tel',
      'data-icon': IconPhone,
      onInput(e) {
        state.values.phone = e.target.value;
        state.touched.phone = true;
        render();
      },
      onBlur() {
        state.touched.phone = true;
        render();
      },
    },
  });

  // ---- Submit button ----

  const btnContent = state.submitting
    ? [h('span', { className: 'btn-spinner' }), 'Sending…']
    : [IconSend(), 'Send Message'];

  const submitBtn = h('button', {
    type: 'submit',
    className: 'submit-btn',
    disabled: !canSubmit || undefined,
  }, ...btnContent);

  // ---- Success banner ----

  const successBanner = state.submitted
    ? h('div', { className: 'success-banner' },
        h('span', { className: 'success-icon' }, IconCheck()),
        h('div', { className: 'success-body' },
          h('h3', {}, 'Message received!'),
          h('p', {}, "Thanks for reaching out. We'll get back to you within one business day.")
        )
      )
    : null;

  // ---- Form ----

  const form = h('form', {
    className: 'contact-form',
    novalidate: '',
    onSubmit(e) {
      e.preventDefault();
      state.touched = { fullName: true, email: true, phone: true };
      const errs = validate(state.values);
      if (Object.keys(errs).length > 0) { render(); return; }
      state.submitting = true;
      render();
      setTimeout(() => {
        state.submitting = false;
        state.submitted  = true;
        render();
      }, 1200);
    },
  },
    fullNameField,
    emailField,
    phoneField,
    h('hr', { className: 'divider' }),
    successBanner,
    submitBtn
  );

  // ---- Page layout ----

  const page = h('div', { className: 'page-wrapper' },
    h('header', { className: 'support-header' },
      h('div', { className: 'badge' }, 'Support'),
      h('h1', {}, 'Contact Us'),
      h('p', {}, 'Have a question or need help? Fill out the form and our team will respond promptly.')
    ),
    h('div', { className: 'card' }, form)
  );

  root.appendChild(page);
}

render();
