const h = (tag, props, ...children) => {
  const el = document.createElement(tag);
  if (props) {
    for (const [key, val] of Object.entries(props)) {
      if (key === 'className')       el.className = val;
      else if (key === 'htmlFor')    el.htmlFor = val;
