function FormField({ id, label, required, inputProps, helperText, errorText }) {
  const hasError = !!errorText;
  const wrapper = h('div', { className: `form-field${hasError ? ' has-error' : ''}` },
    h('label', { htmlFor: id },
      label,
      required
        ? h('span', { className: 'required-star' }, ' *')
        : h('span', { className: 'optional-tag' }, '(optional)')
    ),
    h('div', { className: 'input-wrapper' },
      h('input', { id, ...inputProps }),
      h('span', { className: 'input-icon' }, inputProps['data-icon']())
    ),
    helperText && !hasError
