      type: 'text',
      name: 'fullName',
      placeholder: 'Jane Smith',
      value: state.values.fullName,
      autocomplete: 'name',
      'data-icon': IconUser,
      onInput(e) {
        state.values.fullName = e.target.value;
        state.touched.fullName = true;
        render();
      },
      onBlur() {
        state.touched.fullName = true;
        render();
      },
    },
  });

  const emailField = FormField({
    id: 'email',
    label: 'Email Address',
    required: true,
    errorText: state.touched.email ? errors.email : null,
    inputProps: {
      type: 'email',
      name: 'email',
      placeholder: 'jane@example.com',
      value: state.values.email,
      autocomplete: 'email',
      'data-icon': IconMail,
      onInput(e) {
        state.values.email = e.target.value;
        state.touched.email = true;
        render();
      },
      onBlur() {
        state.touched.email = true;
        render();
      },
    },
  });

  const phoneField = FormField({
    id: 'phone',
    label: 'Phone Number',
    required: false,
    helperText: 'Include country code if outside the US, e.g. +1 (555) 000-0000',
    errorText: state.touched.phone ? errors.phone : null,
    inputProps: {
      type: 'tel',
      name: 'phone',
      placeholder: '+1 (555) 000-0000',
      value: state.values.phone,
      autocomplete: 'tel',
      'data-icon': IconPhone,
      onInput(e) {
        state.values.phone = e.target.value;
        state.touched.phone = true;
        render();
      },
      onBlur() {
        state.touched.phone = true;
        render();
      },
    },
  });

  // ---- Submit button ----

  const btnContent = state.submitting
    ? [h('span', { className: 'btn-spinner' }), 'Sending…']
    : [IconSend(), 'Send Message'];

  const submitBtn = h('button', {
    type: 'submit',
    className: 'submit-btn',
    disabled: !canSubmit || undefined,
  }, ...btnContent);

  // ---- Success banner ----

  const successBanner = state.submitted
    ? h('div', { className: 'success-banner' },
        h('span', { className: 'success-icon' }, IconCheck()),
        h('div', { className: 'success-body' },
          h('h3', {}, 'Message received!'),
          h('p', {}, "Thanks for reaching out. We'll get back to you within one business day.")
        )
      )
    : null;

  // ---- Form ----

  const form = h('form', {
    className: 'contact-form',
    novalidate: '',
    onSubmit(e) {
      e.preventDefault();
      state.touched = { fullName: true, email: true, phone: true };
      const errs = validate(state.values);
      if (Object.keys(errs).length > 0) { render(); return; }
      state.submitting = true;
      render();
      setTimeout(() => {
        state.submitting = false;
        state.submitted  = true;
        render();
      }, 1200);
    },
  },
    fullNameField,
    emailField,
    phoneField,
    h('hr', { className: 'divider' }),
    successBanner,
    submitBtn
  );

  // ---- Page layout ----

  const page = h('div', { className: 'page-wrapper' },
    h('header', { className: 'support-header' },
      h('div', { className: 'badge' }, 'Support'),
      h('h1', {}, 'Contact Us'),
      h('p', {}, 'Have a question or need help? Fill out the form and our team will respond promptly.')
    ),
    h('div', { className: 'card' }, form)
  );

  root.appendChild(page);
}

render();
